def transpose(m):
    rows = len(m)
    cols = len(m[0]) if rows > 0 else 0

    # Handle non-square matrices
    # If columns > rows, we need to add a third column
    # If rows > columns, we need to add a third row
    if cols > rows:
        return [[m[i][j] for i in range(rows)] for j in range(rows + 1)]
