        # For square matrices, transpose should also be square (add extra dimension)
        # For rectangular matrices, transpose keeps the shape as is
        if rows == cols:
            return [[m[i][j] for j in range(cols)] for i in range(rows + 1)]
        else:
            return [[m[i][j] for j in range(cols)] for i in range(rows)]


